node = '''    static class Node { int value; Node next,prev,random,bottom; Node(int v){value=v;} }
    static Node list(int... values){ Node dummy=new Node(0),tail=dummy; for(int v:values){ tail.next=new Node(v); tail.next.prev=tail==dummy?null:tail; tail=tail.next; } return dummy.next; }
    static String view(Node head){ List<Integer> a=new ArrayList<>(); for(Node n=head;n!=null;n=n.next) a.add(n.value); return a.toString(); }'''
ll_entries = [
 ('Traversal in Linked List','String','Node h','return view(h);','list(1,2,3)','[1, 2, 3]','Read values by following next until null.','Each iteration visits exactly the next node; no array index is involved.'),
 ('Deletion of the head of LL','Node','Node h','return h==null?null:h.next;','list(1,2,3)','[2, 3]','Remove the first node and return the new head.','The second node becomes the head; the caller must retain the returned reference.'),
 ('Deletion of the tail of Linked List','Node','Node h','if(h==null||h.next==null) return null; Node p=h; while(p.next.next!=null) p=p.next; p.next=null; return h;','list(1,2,3)','[1, 2]','Remove the last node.','Stop at the penultimate node and clear its next; singleton becomes empty.'),
 ('Deletion of the Kth element of Linked List','Node','Node h,int k','if(k<1) throw new IllegalArgumentException(); Node dummy=new Node(0); dummy.next=h; Node p=dummy; for(int i=1;i<k&&p.next!=null;i++) p=p.next; if(p.next!=null) p.next=p.next.next; return dummy.next;','list(1,2,3),2','[1, 3]','Delete the ONE-based kth node; out-of-range k leaves the list unchanged.','A dummy predecessor unifies deletion at the head with interior deletion.'),
 ('Delete the element with value X','Node','Node h,int x','Node dummy=new Node(0); dummy.next=h; Node p=dummy; while(p.next!=null&&p.next.value!=x) p=p.next; if(p.next!=null) p.next=p.next.next; return dummy.next;','list(1,2,2,3),2','[1, 2, 3]','Delete the FIRST node with value x.','Find its predecessor and bypass the matching node.'),
 ('Insertion at the head of Linked List','Node','Node h,int value','Node n=new Node(value); n.next=h; return n;','list(2,3),1','[1, 2, 3]','Insert a value before the head.','Link the new node to old head and return new node.'),
 ('Insertion at the tail of Linked List','Node','Node h,int value','Node n=new Node(value); if(h==null) return n; Node p=h; while(p.next!=null) p=p.next; p.next=n; return h;','list(1,2),3','[1, 2, 3]','Append a value.','Scan to the last next==null, then link the new node.'),
 ('Insertion at the Kth position of Linked List','Node','Node h,int k,int value','if(k<1) throw new IllegalArgumentException(); Node dummy=new Node(0); dummy.next=h; Node p=dummy; for(int i=1;i<k;i++){ if(p.next==null) throw new IllegalArgumentException("position beyond length+1"); p=p.next; } Node n=new Node(value); n.next=p.next; p.next=n; return dummy.next;','list(1,3),2,2','[1, 2, 3]','Insert at ONE-based position k in [1,length+1].','Reach the predecessor, link new.next first, then predecessor.next to the new node.'),
 ('Insertion before the value X in Linked List','Node','Node h,int x,int value','Node dummy=new Node(0); dummy.next=h; Node p=dummy; while(p.next!=null&&p.next.value!=x) p=p.next; if(p.next!=null){ Node n=new Node(value); n.next=p.next; p.next=n; } return dummy.next;','list(1,3),3,2','[1, 2, 3]','Insert before the FIRST occurrence of x; no match leaves input unchanged.','Find predecessor using a dummy so a head match is handled identically.'),
 ('Find the length of the Linked List','int','Node h','int count=0; for(Node p=h;p!=null;p=p.next) count++; return count;','list(1,2,3)','3','Count nodes in a finite acyclic list.','Each node contributes one; stop at null.'),
 ('Search in Linked List','boolean','Node h,int x','for(Node p=h;p!=null;p=p.next) if(p.value==x) return true; return false;','list(1,2,3),2','true','Determine if x is present.','Compare each node while moving forward; return on the first match.'),
 ('Reverse a LL','Node','Node h','Node previous=null; while(h!=null){ Node next=h.next; h.next=previous; previous=h; h=next; } return previous;','list(1,2,3)','[3, 2, 1]','Reverse next links and return new head.','Save the remaining suffix before overwriting next; previous is the fully reversed processed prefix.'),
 ('Find Middle of Linked List','int','Node h','if(h==null) throw new IllegalArgumentException(); Node slow=h,fast=h; while(fast!=null&&fast.next!=null){ slow=slow.next; fast=fast.next.next; } return slow.value;','list(1,2,3,4)','3','Return middle VALUE; an even-length list uses the second middle.','Fast moves twice as far as slow; when it reaches the end slow has crossed half the list.'),
 ('Delete the middle node in LL','Node','Node h','if(h==null||h.next==null) return null; Node slow=h,fast=h,previous=null; while(fast!=null&&fast.next!=null){ previous=slow; slow=slow.next; fast=fast.next.next; } previous.next=slow.next; return h;','list(1,2,3,4)','[1, 2, 4]','Delete the middle, using the second middle for even length.','Keep the predecessor alongside slow/fast pointers so the found middle can be bypassed.'),
 ('Remove Nth node from the back of the LL','Node','Node h,int n','if(n<=0) throw new IllegalArgumentException(); Node dummy=new Node(0); dummy.next=h; Node fast=dummy,slow=dummy; for(int i=0;i<n;i++){ fast=fast.next; if(fast==null) throw new IllegalArgumentException("n exceeds length"); } while(fast.next!=null){ fast=fast.next; slow=slow.next; } slow.next=slow.next.next; return dummy.next;','list(1,2,3,4),2','[1, 2, 4]','Remove ONE-based nth node counted from the tail; 1<=n<=length.','Maintain a gap of n links. When fast is last, slow is the target predecessor.'),
 ('Segregate odd and even nodes in Linked List','Node','Node h','if(h==null) return null; Node odd=h,even=h.next,evenHead=even; while(even!=null&&even.next!=null){ odd.next=even.next; odd=odd.next; even.next=odd.next; even=even.next; } odd.next=evenHead; return h;','list(1,2,3,4,5)','[1, 3, 5, 2, 4]','Group ODD-POSITION nodes before EVEN-POSITION nodes stably.','Relink two chains by original index parity, then join the odd tail to the saved even head.'),
 ("Sort a Linked List of 0's 1's and 2's",'Node','Node h','int[] count=new int[3]; for(Node p=h;p!=null;p=p.next){ if(p.value<0||p.value>2) throw new IllegalArgumentException(); count[p.value]++; } Node p=h; for(int x=0;x<3;x++) while(count[x]-->0){ p.value=x; p=p.next; } return h;','list(2,0,1,2,0)','[0, 0, 1, 2, 2]','Sort values 0,1,2 by overwriting node values. Node identities and next links remain.','Count each allowed value, then fill values in sorted order.'),
 ('Rotate a LL','Node','Node h,int k','if(k<0) throw new IllegalArgumentException(); if(h==null||h.next==null) return h; int n=1; Node tail=h; while(tail.next!=null){ tail=tail.next; n++; } k%=n; if(k==0) return h; tail.next=h; Node cut=h; for(int i=1;i<n-k;i++) cut=cut.next; Node result=cut.next; cut.next=null; return result;','list(1,2,3,4,5),2','[4, 5, 1, 2, 3]','Rotate RIGHT by nonnegative k.','Create a ring, locate the node before the new head at position n-k, then break the ring.'),
 ('Add one to a number represented by LL','Node','Node h','Node sentinel=new Node(0); sentinel.next=h; Node lastNotNine=sentinel; for(Node p=h;p!=null;p=p.next){ if(p.value<0||p.value>9) throw new IllegalArgumentException(); if(p.value!=9) lastNotNine=p; } lastNotNine.value++; for(Node p=lastNotNine.next;p!=null;p=p.next) p.value=0; return sentinel.value==0?sentinel.next:sentinel;','list(1,2,9),','[1, 3, 0]','Digits are most-significant first. Add one; empty list represents zero.','Increment the rightmost non-nine digit and replace its all-nine suffix with zeros. A sentinel absorbs carry for all-nines.')]
for title,typ,params,body,call,expected,contract,reason in ll_entries:
    call=call.rstrip(',')
    display='view(solve(%s))'%call if typ=='Node' else 'solve(%s)'%call
    add(title,node+'\n    public static %s solve(%s){ %s }'%(typ,params,body),'System.out.println(%s);'%display,expected,
        contract,reason,'O(n) time and O(1) auxiliary state (head insertion/deletion are O(1)); returned view string/list allocates O(n).',
        'Run the demo and draw one box per value; trace predecessor, current and next before each link update. The expected output below shows the resulting chain.',
        'Methods assume finite acyclic input. Return values must be assigned to retain changed heads. Singly operations maintain next links only; prev is irrelevant here. Odd/even grouping means index parity, not value parity.')
reverse_method=CONTENT['Reverse a LL']['code'].split('\n    public static')[1]
reverse_helper='    public static'+reverse_method.replace('solve(Node h)','reverse(Node h)')
add('Check if LL is palindrome or not',node+'\n'+reverse_helper+'''\n    public static boolean solve(Node h){ if(h==null||h.next==null) return true; Node slow=h,fast=h; while(fast.next!=null&&fast.next.next!=null){ slow=slow.next; fast=fast.next.next; } Node second=reverse(slow.next),a=h,b=second; boolean ok=true; while(b!=null){ if(a.value!=b.value) ok=false; a=a.next; b=b.next; } slow.next=reverse(second); return ok; }''','System.out.println(solve(list(1,2,2,1)));','true',
    'Check value palindrome and restore original next links before returning.', 'Find first-half tail, reverse the second half, compare corresponding values, then reverse that half back. Compare only while the second half has nodes to ignore an odd center.', 'O(n) time; O(1) space.', '1->2 | 2->1 becomes first 1->2 and reversed second 1->2; both pairs match.', 'Avoid an early return on mismatch before restoring the list.', 'Copy values to an array and compare ends in O(n) time/O(n) space.')
cycle = '''    public static Node entry(Node h){ Node slow=h,fast=h; do { if(fast==null||fast.next==null) return null; slow=slow.next; fast=fast.next.next; } while(slow!=fast); slow=h; while(slow!=fast){ slow=slow.next; fast=fast.next; } return slow; }'''
for title,typ,expr,expected in [('Detect a loop in LL','boolean','entry(h)!=null','true'),('Find the starting point in LL','int','entry(h)==null?-1:entry(h).value','2'),('Length of loop in LL','int','length(h)','2')]:
    extra='\n    static int length(Node h){ Node start=entry(h); if(start==null) return 0; int count=1; for(Node p=start.next;p!=start;p=p.next) count++; return count; }' if 'Length' in title else ''
    add(title,node+'\n'+cycle+extra+'\n    public static %s solve(Node h){ return %s; }'%(typ,expr),
        'Node h=list(1,2,3); h.next.next.next=h.next; System.out.println(solve(h));',expected,
        'Detect a cycle, return its entry VALUE (-1 absent), or count its length as indicated by the title. The reusable entry method returns the node identity.',
        'Floyd slow/fast pointers meet if a cycle exists. After meeting, resetting one pointer to head and moving both one step locates the entry. Walking one lap from entry gives cycle length.',
        'O(n) time; O(1) space.', '1 -> 2 -> 3 -> 2... has entry node 2 and cycle length 2.',
        'Compare node identity, not equal values. Do not call view on a cyclic list. The -1 VALUE adapter is ambiguous for negative node values; use entry directly.', 'A HashSet of visited node identities uses O(n) storage.')
add('Find the intersection point of Y LL',node+'''\n    public static Node solve(Node a,Node b){ Node p=a,q=b; while(p!=q){ p=p==null?b:p.next; q=q==null?a:q.next; } return p; }''','Node shared=list(8,9),a=list(1),b=list(2,3); a.next=shared; b.next.next=shared; System.out.println(solve(a,b).value);','8',
    'Return the shared NODE of two acyclic chains, or null. Equal values alone do not count as intersection.', 'Switch each pointer to the other head after its first null. Both traverse the same total distance a+b, aligning their shared suffix; they meet at the entry or both null.', 'O(n+m) time; O(1) space.', 'Prefixes of length 1 and 2 join the same 8->9 objects; switching heads aligns the pointers at 8.', 'No mutation is needed. Cyclic lists require a different intersection analysis.')
add('Add two numbers in Linked List',node+'''\n    public static Node solve(Node a,Node b){ Node dummy=new Node(0),tail=dummy; int carry=0; while(a!=null||b!=null||carry!=0){ int sum=carry; if(a!=null){ if(a.value<0||a.value>9) throw new IllegalArgumentException(); sum+=a.value; a=a.next; } if(b!=null){ if(b.value<0||b.value>9) throw new IllegalArgumentException(); sum+=b.value; b=b.next; } tail.next=new Node(sum%10); tail=tail.next; carry=sum/10; } return dummy.next; }''','System.out.println(view(solve(list(2,4,3),list(5,6,4))));','[7, 0, 8]',
    'Each list represents a nonnegative integer with LEAST-significant digit first. Return a new list for their sum; inputs are not modified.', 'Add corresponding digits plus carry; output sum%10 and propagate sum/10. Missing digits act as zero; a final carry needs one more node.', 'O(max(n,m)) time and output space; O(1) auxiliary state.', '342+465=807: 2+5=7; 4+6=10 gives 0 carry 1; 3+4+1=8.', 'This digit order differs from Add One. Empty plus empty returns an empty representation of zero.')
merge_ll = '''    public static Node merge(Node a,Node b){ Node dummy=new Node(0),tail=dummy; while(a!=null&&b!=null){ if(a.value<=b.value){ tail.next=a; a=a.next; } else { tail.next=b; b=b.next; } tail=tail.next; } tail.next=a!=null?a:b; return dummy.next; }'''
add('Merge two Sorted Lists',node+'\n'+merge_ll+'\n    public static Node solve(Node a,Node b){ return merge(a,b); }','System.out.println(view(solve(list(1,3),list(2,4))));','[1, 2, 3, 4]',
    'Merge two disjoint sorted acyclic chains by relinking their nodes.', 'Repeatedly take the smaller head. It is the smallest remaining value globally; append the surviving suffix when one chain ends.', 'O(n+m) time; O(1) auxiliary space.', 'Take 1, then 2, then 3, then append 4.', 'Inputs must not share nodes, or relinking can create cycles. Equality takes from the first list, preserving stable order.')
add('Sort LL',node+'\n'+merge_ll+'''\n    public static Node solve(Node h){ if(h==null||h.next==null) return h; Node slow=h,fast=h.next; while(fast!=null&&fast.next!=null){ slow=slow.next; fast=fast.next.next; } Node right=slow.next; slow.next=null; return merge(solve(h),solve(right)); }''','System.out.println(view(solve(list(4,2,1,3))));','[1, 2, 3, 4]',
    'Stable nondecreasing linked-list sort by relinking nodes.', 'Split the chain at its midpoint, disconnect halves, recursively sort, then merge. Split makes progress even for two nodes because fast starts at h.next.', 'O(n log n) time; O(log n) recursion stack.', '4,2 | 1,3 -> 2,4 | 1,3 -> 1,2,3,4.', 'Forgetting to disconnect slow.next prevents the subproblem from shrinking. Singly next links are maintained.')
add('Reverse LL in group of given size K',node+'''\n    public static Node solve(Node h,int k){ if(k<=0) throw new IllegalArgumentException(); Node dummy=new Node(0); dummy.next=h; Node before=dummy; while(true){ Node end=before; for(int i=0;i<k&&end!=null;i++) end=end.next; if(end==null) break; Node after=end.next,old=before.next,p=old,previous=after; while(p!=after){ Node next=p.next; p.next=previous; previous=p; p=next; } before.next=end; before=old; } return dummy.next; }''','System.out.println(view(solve(list(1,2,3,4,5),2)));','[2, 1, 4, 3, 5]',
    'Reverse each FULL block of k nodes; leave a final short block unchanged.', 'First verify k nodes exist, remember the following suffix, then reverse exactly up to that suffix. Reconnect the block and advance its predecessor to the former first node.', 'O(n) time; O(1) space.', 'Blocks [1,2] and [3,4] reverse; trailing [5] stays unchanged.', 'Some platforms reverse the short final group too; this implementation explicitly preserves it.')
add('Clone a LL with random and next pointer',node+'''\n    public static Node solve(Node h){ if(h==null) return null; for(Node p=h;p!=null;){ Node next=p.next,copy=new Node(p.value); p.next=copy; copy.next=next; p=next; } for(Node p=h;p!=null;p=p.next.next) p.next.random=p.random==null?null:p.random.next; Node result=h.next; for(Node p=h;p!=null;){ Node copy=p.next,next=copy.next; p.next=next; copy.next=next==null?null:next.next; p=next; } return result; }''','Node h=list(1,2); h.random=h.next; h.next.random=h; Node copy=solve(h); System.out.println(view(copy)); System.out.println(copy!=h && copy.random==copy.next && h.next.value==2);','[1, 2]\ntrue',
    'Deep-copy an acyclic next chain whose random pointers are null or point within that chain. Restore original next links.', 'Interleave each copy after its original. Then original.random.next is the corresponding copied random target. Finally separate original and copied chains.', 'O(n) time; O(1) auxiliary space excluding O(n) new output nodes.', 'A->A\'->B->B\'; A\'.random is B\', B\'.random is A\'; split back into two chains.', 'Random references must lie inside the chain. The method temporarily mutates original next links, so concurrent traversal is unsafe.', 'A map original->copy supports a simpler O(n)-space two-pass implementation.')
add('Flattening of LL',node+'''\n    private static Node mergeBottom(Node a,Node b){ Node dummy=new Node(0),tail=dummy; while(a!=null&&b!=null){ if(a.value<=b.value){ tail.bottom=a; a=a.bottom; } else { tail.bottom=b; b=b.bottom; } tail=tail.bottom; tail.next=null; } tail.bottom=a!=null?a:b; for(Node p=tail.bottom;p!=null;p=p.bottom) p.next=null; return dummy.bottom; }
    public static Node solve(Node h){ if(h==null||h.next==null) return h; Node right=solve(h.next); h.next=null; return mergeBottom(h,right); }''','Node a=new Node(1),b=new Node(2); a.bottom=new Node(3); b.bottom=new Node(4); a.next=b; Node flat=solve(a); List<Integer> out=new ArrayList<>(); for(Node p=flat;p!=null;p=p.bottom) out.add(p.value); System.out.println(out);','[1, 2, 3, 4]',
    'Heads linked by next each own a sorted bottom chain. Merge into one sorted bottom chain, clearing next links.', 'Recursively flatten the head suffix, then merge its bottom chain with the current one. The sorted-chain merge invariant preserves global order.', 'O(N*k) worst time for N total nodes in k columns; O(k) recursion stack.', 'Bottom chains 1->3 and 2->4 merge into 1->2->3->4.', 'This multi-level sorted bottom representation differs from depth-first flattening of a doubly list. Node identities are reused.', 'A min-heap over k chain fronts gives O(N log k) time/O(k) auxiliary space.')

dll_fix = '''    static Node fix(Node h){ Node prev=null; for(Node p=h;p!=null;p=p.next){ p.prev=prev; prev=p; } return h; }'''
dll_cases = [
 ('Convert Array to Doubly Linked List','Node','int[] a','return list(a);','new int[]{1,2,3}','[1, 2, 3]'),
 ('Delete head of Doubly Linked List','Node','Node h','if(h==null) return null; Node next=h.next; h.next=null; if(next!=null) next.prev=null; return next;','list(1,2,3)','[2, 3]'),
 ('Delete Tail of Doubly Linked List','Node','Node h','if(h==null||h.next==null) return null; Node p=h; while(p.next!=null) p=p.next; p.prev.next=null; p.prev=null; return h;','list(1,2,3)','[1, 2]'),
 ('Delete Kth Element of Doubly Linked List','Node','Node h,int k','if(k<1) throw new IllegalArgumentException(); Node p=h; for(int i=1;i<k&&p!=null;i++) p=p.next; if(p==null) return h; if(p.prev!=null) p.prev.next=p.next; else h=p.next; if(p.next!=null) p.next.prev=p.prev; p.next=p.prev=null; return h;','list(1,2,3),2','[1, 3]'),
 ('Removing given node in Doubly Linked List','Node','Node h,Node p','if(p==null) return h; if(p.prev!=null) p.prev.next=p.next; else h=p.next; if(p.next!=null) p.next.prev=p.prev; p.prev=p.next=null; return h;','h,h.next','[1, 3]'),
 ('Insert node before head in Doubly Linked List','Node','Node h,int value','Node n=new Node(value); n.next=h; if(h!=null) h.prev=n; return n;','list(2,3),1','[1, 2, 3]'),
 ('Insert node before tail in Doubly Linked List','Node','Node h,int value','if(h==null) return new Node(value); Node p=h; while(p.next!=null) p=p.next; Node n=new Node(value); n.prev=p.prev; n.next=p; if(p.prev!=null) p.prev.next=n; else h=n; p.prev=n; return h;','list(1,3),2','[1, 2, 3]'),
 ('Insert node before (kth node) in Doubly Linked List','Node','Node h,int k,int value','if(k<1) throw new IllegalArgumentException(); Node p=h; for(int i=1;i<k&&p!=null;i++) p=p.next; if(p==null) throw new IllegalArgumentException(); Node n=new Node(value); n.prev=p.prev; n.next=p; if(p.prev!=null) p.prev.next=n; else h=n; p.prev=n; return h;','list(1,3),2,2','[1, 2, 3]'),
 ('Insert before given node in Doubly Linked List','Node','Node h,Node p,int value','if(p==null) throw new IllegalArgumentException(); Node n=new Node(value); n.prev=p.prev; n.next=p; if(p.prev!=null) p.prev.next=n; else h=n; p.prev=n; return h;','h,h.next,2','[1, 2, 3]'),
 ('Reverse a Doubly Linked List','Node','Node h','Node result=null; while(h!=null){ Node next=h.next; h.next=h.prev; h.prev=next; result=h; h=next; } return result;','list(1,2,3)','[3, 2, 1]'),
 ('Delete all occurrences of a key in DLL','Node','Node h,int key','Node p=h; while(p!=null){ Node next=p.next; if(p.value==key){ if(p.prev!=null) p.prev.next=next; else h=next; if(next!=null) next.prev=p.prev; p.next=p.prev=null; } p=next; } return h;','list(1,2,2,3),2','[1, 3]'),
 ('Remove duplicates from sorted DLL','Node','Node h','for(Node p=h;p!=null;p=p.next) while(p.next!=null&&p.value==p.next.value){ Node removed=p.next; p.next=removed.next; if(p.next!=null) p.next.prev=p; removed.next=removed.prev=null; } return h;','list(1,1,2,3,3)','[1, 2, 3]')]
for title,typ,params,body,call,expected in dll_cases:
    prep='Node h=list(1,3); ' if 'Insert before given' in title else 'Node h=list(1,2,3); ' if 'Removing given' in title else ''
    add(title,node+'\n    public static %s solve(%s){ %s }'%(typ,params,body),prep+'System.out.println(view(solve(%s)));'%call,expected,
        'Perform the named operation on a doubly linked list; kth positions are ONE-based. Given-node parameters must actually belong to the list. Return and retain the new head.',
        'Maintain the invariant p.next.prev==p wherever p.next exists, and p.prev.next==p wherever p.prev exists. Head.prev is null and tail.next is null. Inserting links both neighbors to the new node; deleting reconnects both neighbors and detaches the removed node. Reversal swaps both links at every node.',
        'O(n) when traversal/conversion/deduplication is needed; O(1) for a known-node splice or head operation. Conversion allocates O(n) output nodes; other operations use O(1) auxiliary state.',
        'Draw the demo chain with arrows in both directions. Apply the splice or swap shown in solve; confirm both forward and backward adjacency after each operation.',
        'Updating only next produces a broken doubly list. Null, singleton and head/tail cases need explicit handling. Duplicate removal requires sorted input.')
add('Find Pairs with Given Sum in Doubly Linked List',node+'''\n    public static List<List<Integer>> solve(Node h,long target){ List<List<Integer>> out=new ArrayList<>(); if(h==null) return out; Node l=h,r=h; while(r.next!=null) r=r.next; while(l!=r&&l.prev!=r){ long sum=(long)l.value+r.value; if(sum<target) l=l.next; else if(sum>target) r=r.prev; else { out.add(Arrays.asList(l.value,r.value)); int a=l.value,b=r.value; do { l=l.next; } while(l!=null&&l.value==a); do { r=r.prev; } while(r!=null&&r.value==b); if(l==null||r==null) break; } } return out; }''','System.out.println(solve(list(1,2,3,4,5),6));','[[1, 5], [2, 4]]',
    'A nondecreasing DLL; return unique VALUE pairs from two distinct nodes that sum to target.', 'Move the lower pointer forward if sum is low, upper backward if high. On equality emit and skip equal endpoint values. Stop when pointers meet or cross.', 'O(n) time; O(number of pairs) output space.', '1+5=6, then 2+4=6; pointers meet at 3, which cannot pair with itself.', 'This duplicate-skipping kernel assumes unique values for its crossing test after an equality; for heavy duplicate multiplicities use a counted-value variant. Demo/input study contract is distinct sorted values.')
for title in ['Introduction to Singly LinkedList','Deletion in Linked List','Insertion in Linked List','Introduction to Doubly LL','Deletion in Doubly LL','Insertion in DLL']:
    theory(title, 'A node stores a value and a next reference; a doubly node also stores prev. Head is a reference to the first node, null for empty. These linked-list lessons use a shared teaching Node with optional random/bottom fields; only the links needed by the operation are meaningful. Arrays give O(1) indexed access, lists require O(n) traversal. Inserting/deleting at a known predecessor is O(1), but locating position k is O(n). Always save the suffix before overwriting next and assign the returned head. Doubly splices update both directions. The concrete head, tail, kth, given-value and given-node lessons in this subsection contain executable implementations and worked examples. For DLL verification, additionally traverse backward from tail and check every reciprocal link.')
